import{_ as a,H as t,f as n,i}from"./chunks/framework.BH2BK_3i.js";const G=JSON.parse('{"title":"16 | 垃圾回收器（下）：面向未来的ZGC、Shenandoah","description":"","frontmatter":{},"headers":[{"level":2,"title":"ZGC 的由来","slug":"zgc-的由来","link":"#zgc-的由来","children":[]},{"level":2,"title":"ZGC VS G1","slug":"zgc-vs-g1","link":"#zgc-vs-g1","children":[]},{"level":2,"title":"ZGC 的黑科技：颜色指针","slug":"zgc-的黑科技-颜色指针","link":"#zgc-的黑科技-颜色指针","children":[]},{"level":2,"title":"ZGC 的垃圾回收过程","slug":"zgc-的垃圾回收过程","link":"#zgc-的垃圾回收过程","children":[]},{"level":2,"title":"ZGC 的最佳实践","slug":"zgc-的最佳实践","link":"#zgc-的最佳实践","children":[{"level":3,"title":"分配合适的内存","slug":"分配合适的内存","link":"#分配合适的内存","children":[]},{"level":3,"title":"调整并发线程","slug":"调整并发线程","link":"#调整并发线程","children":[]},{"level":3,"title":"注意资源限制","slug":"注意资源限制","link":"#注意资源限制","children":[]},{"level":3,"title":"启用垃圾收集日志","slug":"启用垃圾收集日志","link":"#启用垃圾收集日志","children":[]},{"level":3,"title":"监控和调优","slug":"监控和调优","link":"#监控和调优","children":[]}]},{"level":2,"title":"Shenandoah","slug":"shenandoah","link":"#shenandoah","children":[]},{"level":2,"title":"重点回顾","slug":"重点回顾","link":"#重点回顾","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]},{"level":2,"title":"点亮你的知识框架图","slug":"点亮你的知识框架图","link":"#点亮你的知识框架图","children":[]}],"relativePath":"云时代的JVM原理与实战/16｜垃圾回收器（下）：面向未来的ZGC、Shenandoah.md","filePath":"云时代的JVM原理与实战/16｜垃圾回收器（下）：面向未来的ZGC、Shenandoah.md","lastUpdated":1795541359000}'),l={name:"云时代的JVM原理与实战/16｜垃圾回收器（下）：面向未来的ZGC、Shenandoah.md"};function s(h,e,p,o,r,c){return t(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="_16-垃圾回收器-下-面向未来的zgc、shenandoah" tabindex="-1">16 | 垃圾回收器（下）：面向未来的ZGC、Shenandoah <a class="header-anchor" href="#_16-垃圾回收器-下-面向未来的zgc、shenandoah" aria-label="Permalink to &quot;16 | 垃圾回收器（下）：面向未来的ZGC、Shenandoah&quot;">​</a></h1><p>你好，我是康杨。</p><p>今天我们继续来聊 GC 的话题，上一节课我们介绍了当前生产环境中 GC 的王者 G1，还记得它的特点吗？没错，就是垃圾优先、可预见性、并行、分区分代，我们也说过 G1 是一个承前启后的垃圾回收器，而它启的这个后就是 ZGC 和 Shenandoah，也就是我们今天的主角，它们代表着未来 GC 的主流。</p><h2 id="zgc-的由来" tabindex="-1">ZGC 的由来 <a class="header-anchor" href="#zgc-的由来" aria-label="Permalink to &quot;ZGC 的由来&quot;">​</a></h2><p>随着云计算和大数据的迅猛发展，现代应用程序对于扩展性和低延迟的需求越来越高。传统的垃圾收集器在处理大内存应用程序时经常面临长时间停顿的问题，这导致了应用程序的性能下降。</p><p>为了解决这个问题，Oracle 决定开发一种全新的垃圾收集器，旨在提供低停顿时间、高可伸缩性和适用于大内存应用程序的解决方案。于是在 2017 年，Oracle 推出了名为 ZGC 的垃圾收集器，首先作为 Oracle JDK 的一个实验性功能引入。在随后的几个版本中，Oracle 对ZGC 进行了改进和优化，不断增加新功能，提升性能，并解决了一些问题。最终，ZGC 在JDK 11 中正式成为 Oracle JDK 的一部分，摇身一变，成为了一种稳定的垃圾收集器，并提供商业支持。</p><p>与此同时，ZGC 也在 OpenJDK 中不断得到改进。Oracle 把 ZGC 的源代码提交给了OpenJDK 社区，供社区成员参与测试、优化。自 JDK 11 起，OpenJDK 把 ZGC 作为它垃圾收集器的一部分，并在 OpenJDK 的发行版本中提供了稳定版本，供开源社区使用和改进。</p><p>在 ZGC 的演进过程中，Oracle 和 OpenJDK 社区不断改进 ZGC 的性能、可靠性和功能。为了保证获取到最新的引用信息，ZGC 使用了读屏障技术来捕获引用关系的变化。除此之外，ZGC 也具有支持大型堆内存的功能，最高可达 16TB 的堆内存容量。这对于需要处理大量数据的应用程序非常有用。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E6%97%B6%E4%BB%A3%E7%9A%84JVM%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/16/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E6%97%B6%E4%BB%A3%E7%9A%84JVM%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/16/1.png" alt=""></a></p><p>ZGC 还被设计得易于使用和调试。它的配置参数相对较少，简化了使用和调优的复杂性，使开发人员能够更轻松地应用和优化。</p><p>总的来说，ZGC 是一种专为高并发和大内存应用场景设计的垃圾收集器，具备可伸缩性、低停顿时间、大堆内存支持和易用性等特点。</p><p>它的引入给开发人员提供了一种高性能的解决方案，尤其在大数据处理和高并发应用中发挥重要作用。ZGC 通过使用一些先进的技术和算法，实现了这些特点和功能。在开始介绍 ZGC 之前，我们先来对比一下 ZGC 和我们之前介绍的 G1。</p><h2 id="zgc-vs-g1" tabindex="-1">ZGC VS G1 <a class="header-anchor" href="#zgc-vs-g1" aria-label="Permalink to &quot;ZGC VS G1&quot;">​</a></h2><p>G1 在回收过程中存在两个基本阶段：标记阶段和清除阶段。</p><p>在标记阶段，GC 会找出所有需要被清除的对象。然后在清除阶段，GC 会清除那些已经被标记的对象。这个过程所有的应用线程都需要暂停。然而在 ZGC 中情况有所改变。ZGC 使用了一种叫做“并行”的方式来进行垃圾收集，这解决了 G1 必须停顿的问题。</p><p>并行处理意味着 ZGC 可以同时进行标记和清除这两个动作，而不是像 G1 和 CMS 那样等待标记阶段完成后再进行清除。这样，ZGC 可以在可预见的暂停时间内更好地处理大型数据集。</p><p>举一个简单的例子，假设我们有一个大型数据集，里面有 1000 万个对象，这对于 G1 和 CMS来说可能需要几秒钟甚至更长的时间来完成垃圾回收的过程，因为它们需要先标记所有的对象，然后再进行清除。而在 ZGC 中，由于标记和清除可以同时进行，即使数据集非常大，它也能在预设的暂停时间内完成垃圾回收。</p><p>当然，这个过程在实际的代码中可能需要更复杂的操作，但是这个例子能够帮助你理解 ZGC如何处理大型数据集，以及它与 G1 之间的区别。</p><p>总的来说，ZGC 解决了 G1 在处理大型数据集时可能产生的暂停、无法实时回收垃圾的问题。在实际应用中，ZGC 的并行处理方式已经得到了证实，无论数据集有多大，都能在可预见的暂停时间内完成垃圾回收。这就是 ZGC 的魅力所在。</p><p>接下来，让我们看看 ZGC 和 G1 更详细的对比。</p><ol><li><p>首先是低延迟。ZGC 的设计目标是实现低延迟，不管堆内存大小如何，都能保证垃圾回收的停顿时间在 10 毫秒以内。相比之下，虽然 G1 也设计成了低延迟，但在处理大规模数据的时候，它们的停顿时间往往超过了 10 毫秒。</p></li><li><p>其次是并发工作。ZGC 的另一个亮点是它可以在应用程序运行时进行垃圾回收。而 G1 的并发模式会在一些阶段需要 Java 线程停下来等待，这会影响程序性能。</p></li><li><p>最后是内存压缩。ZGC 支持内存压缩，也就是把活跃对象压缩到内存的一部分，从而释放更多内存空间。而 G1 则需要额外的 Full GC 操作来实现相同的效果。</p></li></ol><p>那 ZGC 是如何实现这么多功能的呢？靠的就是 ZGC 的黑科技——颜色指针。</p><h2 id="zgc-的黑科技-颜色指针" tabindex="-1">ZGC 的黑科技：颜色指针 <a class="header-anchor" href="#zgc-的黑科技-颜色指针" aria-label="Permalink to &quot;ZGC 的黑科技：颜色指针&quot;">​</a></h2><p>ZGC 和传统的 Java 垃圾收集器不同的地方在于它的 GC 信息是存储在指针里的，而不是对象头部。为了实现这一点，ZGC 利用了 64 位机器的一些位来存储垃圾收集信息。具体来说，在64 位机器上，第 42 位用来描述实际的虚拟内存地址，接下来的 4 位（第 43 位～第 46 位）用来描述元数据，最后的 17 位是固定的。</p><p>此外，ZGC 还引入了一种叫做颜色指针的技术，来提高垃圾回收器的效率，降低停顿时间。在并发标记阶段，颜色指针可以帮助垃圾回收器判断对象是否已经被标记为活动或非活动状态，从而避免在并发标记过程中使用读屏障捕获引用关系的变化，降低垃圾回收的开销和停顿时间。简单来说，在垃圾收集期间，如果一个对象被颜色指针标记为“黑色”，那就表示它是活动的，否则就是非活动的。通过这种方式，颜色指针在不侵入传统垃圾收集的基础上提高了垃圾收集的效率和降低了停顿时间。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E6%97%B6%E4%BB%A3%E7%9A%84JVM%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/16/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E6%97%B6%E4%BB%A3%E7%9A%84JVM%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/16/2.png" alt=""></a></p><p>总的来说，ZGC 通过将垃圾收集信息存储在指针中并引入颜色指针技术，实现了高效的垃圾回收和内存管理。而基于这些能力，ZGC 的垃圾回收过程也与众不同。</p><h2 id="zgc-的垃圾回收过程" tabindex="-1">ZGC 的垃圾回收过程 <a class="header-anchor" href="#zgc-的垃圾回收过程" aria-label="Permalink to &quot;ZGC 的垃圾回收过程&quot;">​</a></h2><p>ZGC 就像一个超级高效的管家，它负责一个巨大的商场，那些门店就像是你的程序，而那些正在出售的商品就好比是对象。当 ZGC 来到工作岗位时，它马上开始检查标签。它瞥见每一个对象商品，然后贴上一个“Remapped”的标签，表示这些商品需要重新整理。</p><p>紧接着，ZGC 像一个精密的机器，瞬间开始扫描每一件商品，看看哪些商品正在被顾客浏览和购买。对于这些商品，它会把它们的标签改成 M0。意思就是这些商品是活跃的，正在被使用。</p><p>完成扫描后，ZGC 进入并发标记阶段，开始更深层次的检查。它开始一一检查每个商品的详细信息，包括它们的价格、位置、顾客的喜爱程度等等。检查完之后，它注意到有些商品已经过时了或者没有顾客感兴趣。这些商品就像是内存里不再需要的对象。于是进入了回收阶段，它准备进行清理这些对象。它计算每个货架上的商品情况，如果某个货架上的过时商品超过了货架数的 25%，这个货架就会被选中进行整理。</p><p>清理完成后，ZGC 来到了初始转移阶段。它开始重新布局，让更多的热门商品占据主要位置。同样，它会移动内存中的活跃对象，这就是初始转移阶段。每一个被移动的商品，它都会把标签从 M0 变更成 M1。</p><p>ZGC 在忙于上述的工作的同时，还得监控商场的情况。这就是读屏障的作用。每当有顾客想要购买某个商品时，它都会检查那个商品的标签是不是 M0，如果是，它就会帮顾客把商品挪到结账区，并把那个商品的标签改为“M1”。</p><p>与此同时，ZGC 比起其他的垃圾回收器，比如 G1 或者 CMS，它有一个巨大的优势：它可以一边让顾客继续购物（程序运行）一边做清理和整理工作。也就是说，你的顾客（程序）根本感觉不到背后正在进行的清理工作，他们可以无阻碍地继续购物（程序运行）。之所以能实现这种效果，是因为相比于 G1 采用写屏障的方式，ZGC 采用的是读屏障的方式。</p><p>ZGC 就好像是一位无所不能的管家，它一手掌控着商场的运行，一手高效地进行商品的整理和清理，让顾客能愉快地购物，同时保证商场高效且有序地运行。这就是 ZGC 垃圾回收器的工作流程，也是它能提供更高性能的秘密。</p><h2 id="zgc-的最佳实践" tabindex="-1">ZGC 的最佳实践 <a class="header-anchor" href="#zgc-的最佳实践" aria-label="Permalink to &quot;ZGC 的最佳实践&quot;">​</a></h2><p>作为新型的 GC，如何更好地使用 ZGC？我整理了 ZGC 使用的最佳实践，你可以参考下。</p><h3 id="分配合适的内存" tabindex="-1">分配合适的内存 <a class="header-anchor" href="#分配合适的内存" aria-label="Permalink to &quot;分配合适的内存&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>根据应用程序的内存需求和系统资源，使用 -Xmx 参数设置合适的最大堆内存大小。确保为应</span></span></code></pre></div><p>用程序提供足够的内存空间，避免频繁地垃圾收集导致性能下降。</p><h3 id="调整并发线程" tabindex="-1">调整并发线程 <a class="header-anchor" href="#调整并发线程" aria-label="Permalink to &quot;调整并发线程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>根据应用程序的性能需求和系统配置，使用 -XX:ConcGCThreads 和 -</span></span>
<span class="line"><span>XX:ParallelGCThreads 参数调整并发 GC 线程和并行 GC 线程的数量。适当增加并行线</span></span></code></pre></div><p>程的数量可以加快标记和整理操作的速度，提高垃圾收集的效率。</p><h3 id="注意资源限制" tabindex="-1">注意资源限制 <a class="header-anchor" href="#注意资源限制" aria-label="Permalink to &quot;注意资源限制&quot;">​</a></h3><p>如果应用程序运行在有限的硬件资源上，如 CPU 核心数、内存容量等，确保不超过系统的限制。避免过度配置并发和并行线程的数量，以免竞争资源导致性能下降。</p><h3 id="启用垃圾收集日志" tabindex="-1">启用垃圾收集日志 <a class="header-anchor" href="#启用垃圾收集日志" aria-label="Permalink to &quot;启用垃圾收集日志&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在调试和优化阶段，启用垃圾收集日志，使用 -XX:+UnlockExperimentalVMOptions -</span></span>
<span class="line"><span>XX:+UseZGC -Xlog:gc* 参数，以便查看 GC 日志，了解内存分配和回收情况，并识别潜</span></span></code></pre></div><p>在的性能问题。</p><h3 id="监控和调优" tabindex="-1">监控和调优 <a class="header-anchor" href="#监控和调优" aria-label="Permalink to &quot;监控和调优&quot;">​</a></h3><p>使用合适的监控工具监视应用程序的内存使用和垃圾收集性能。根据监控数据进行调优，例如调整垃圾收集相关参数或进行代码优化，提高应用程序的性能和可伸缩性。</p><p>ZGC 适用于具有大内存需求和对低停顿时间敏感的应用程序，例如大型数据库、内存缓存和大数据处理等。根据具体的应用程序和系统配置进行实验和性能测试，以找到最适合的参数和配置。在生产环境中使用 ZGC 的时候，你还要确保使用 Java 11 或更高版本的 JDK。</p><h2 id="shenandoah" tabindex="-1">Shenandoah <a class="header-anchor" href="#shenandoah" aria-label="Permalink to &quot;Shenandoah&quot;">​</a></h2><p>和 ZGC 一样，Shenandoah 也是一款为减少停顿时间而设计的垃圾收集器。它们的共同目标还包括减少垃圾收集对应用程序的影响，让应用程序在垃圾收集过程中继续运行。</p><p>但在关键的技术方面，它们有一些区别。Shenandoah 使用转发指针来重新定向对象的引用，而 ZGC 则使用额外的重定位信息来跟踪对象的引用。此外，Shenandoah 使用连接矩阵来记录对象之间的引用关系，在并发标记和清理时起着重要作用。相比之下，ZGC 则通过屏障器来追踪对象引用的变化，而不需要连接矩阵。</p><p>总之，Shenandoah 和 ZGC 都致力于减少停顿时间的垃圾收集，不过也有各自的特点和应用场景，你在选择适合的垃圾收集器时，需要综合考虑应用程序的需求和环境。</p><h2 id="重点回顾" tabindex="-1">重点回顾 <a class="header-anchor" href="#重点回顾" aria-label="Permalink to &quot;重点回顾&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E6%97%B6%E4%BB%A3%E7%9A%84JVM%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/16/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E6%97%B6%E4%BB%A3%E7%9A%84JVM%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/16/3.png" alt=""></a></p><p>ZGC 在战略上沿用了前几代垃圾回收器的算法策略，采用并发标记和并发清理的思路，在战术上通过颜色指针等技术达到更理想的并发清理。但 ZGC 同样不是银弹，它也有自身的优缺点。</p><p>它的优势在于一旦一个内存区域的活跃对象被移走，这个区域就可以立即得到清空和重复利用，不用等待所有针对这个区域的引用修正完成；颜色指针降低了内存屏障的使用频次，只使用了读取屏障；颜色指针显示出高扩展能力，可以记录与对象标记、重新定位相关的信息，以提高性能。</p><p>它的劣势在于对快速分配的对象分配速度存在一定的约束，长时间保持高分配速度会导致全并发收集周期过长，且回收的内存空间小于并发生成的浮动垃圾占据的空间，导致堆内可移动的剩余空间逐步减少；吞吐量低于 G1，尤其是在堆比较小的情况下，ZGC 的性能损失可能达到5% 到 15%。</p><p>所以说，ZGC 并不是一个全新的垃圾回收器，而是在前几代垃圾回收器的基础上进行了优化。它的出色表现有可能改变未来的编程方式，垃圾回收器喜欢不可变对象，因为它们更容易处理。有了 ZGC 强大的回收能力，我们不用再担心内存和垃圾回收的限制，可以大胆地使用不可变对象进行代码编写。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>你在工作中用的是哪种垃圾回收器，你觉得在你的工作环境中它的优缺点是什么？</p><p>欢迎你把你的经验分享到评论区，也欢迎你把这节课的内容分享给其他朋友，我们下节课再见！</p><h2 id="点亮你的知识框架图" tabindex="-1">点亮你的知识框架图 <a class="header-anchor" href="#点亮你的知识框架图" aria-label="Permalink to &quot;点亮你的知识框架图&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E6%97%B6%E4%BB%A3%E7%9A%84JVM%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/16/4.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E6%97%B6%E4%BB%A3%E7%9A%84JVM%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/16/4.jpeg" alt=""></a></p>`,66)])])}const C=a(l,[["render",s]]);export{G as __pageData,C as default};
